public sealed class LoyaltyDiscountPolicy
{
    public int CalculatePayableTotal(LoyaltyTier tier, int subtotalCents)
    {
        var rate = BaseRate(tier) + OrderSizeBonus(subtotalCents);
        var effectiveRate = Math.Min(rate, 10);
        var discountCents = subtotalCents * effectiveRate / 100;

        return subtotalCents - discountCents;
    }

    private static int BaseRate(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };

    private static int OrderSizeBonus(int subtotalCents) => subtotalCents switch
    {
        < 5000 => 0,
        < 20000 => 1,
        _ => 3
    };
}
''')
